if (timeout) {
	DEFINE_WAIT_FUNC(wait, woken_wake_function);

	if (!sk_sleep(sk))
		return;

	add_wait_queue(sk_sleep(sk), &wait);

	do {
		if (sk_wait_event(sk, &timeout,
				  sock_flag(sk, SOCK_DONE), &wait))
			break;
	} while (!signal_pending(current) && timeout);

	remove_wait_queue(sk_sleep(sk), &wait);
}

